#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int ROOM = -1;
const int REAC = -2;
const int BAD_REAC = -3;
const int CAPS = ROOM;

int cells[MAXN][MAXN], podCount[MAXN][MAXN];
int venom[61][MAXN][MAXN];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

struct Point {
    int x, y, number;
    Point(int a = 0, int b = 0, int c = 0) : x(a), y(b), number(c) {}
};

vector<Point> survivors, pods;

bool isRoom(int x, int y, int N) {
    return x >= 0 && x < N && y >= 0 && y < N && cells[x][y] == ROOM;
}

int cellType(char c) {
    if (c >= '0' && c <= '9') return ROOM;
    if (c == 'Y') return REAC;
    if (c == 'Z') return BAD_REAC;
    return -1;
}

int cellValue(char c) {
    return c - '0';
}

void propagateVenom(int startX, int startY, int T, int N) {
    venom[0][startX][startY] = 1;

    for (int t = 1; t <= T; ++t) {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if (venom[t - 1][i][j]) {
                    venom[t][i][j] = 1;

                    for (int d = 0; d < 4; ++d) {
                        int nx = i + dx[d];
                        int ny = j + dy[d];

                        if (isRoom(nx, ny, N)) {
                            venom[t][nx][ny] = 1;
                        }
                    }
                }
            }
        }
    }
}

int distTo(const Point &a, const Point &b, int N, int limit) {
    vector<bitset<MAXN>> visited(N);
    queue<pair<int, Point>> q;
    q.push({0, a});
    visited[a.x][a.y] = 1;

    while (!q.empty()) {
        int time = q.front().first;
        Point cur = q.front().second;
        q.pop();

        if (cur.x == b.x && cur.y == b.y) return time;
        if (time == limit) continue;
        if (venom[time][cur.x][cur.y]) continue;

        for (int d = 0; d < 4; ++d) {
            Point nxt(cur.x + dx[d], cur.y + dy[d], 0);

            if (isRoom(nxt.x, nxt.y, N) && !visited[nxt.x][nxt.y] && !venom[time][nxt.x][nxt.y]) {
                visited[nxt.x][nxt.y] = 1;
                q.push({time + 1, nxt});
            }
        }
    }

    return 999;
}

class Dinic {
    struct Edge {
        int to, rev, cap, flow;
    };

    int n;
    vector<vector<Edge>> graph;
    vector<int> level, ptr;

public:
    Dinic(int _n) : n(_n), graph(_n), level(_n), ptr(_n) {}

    void addEdge(int u, int v, int capacity) {
        Edge a = {v, (int)graph[v].size(), capacity, 0};
        Edge b = {u, (int)graph[u].size(), 0, 0};
        graph[u].push_back(a);
        graph[v].push_back(b);
    }

    bool buildLevels(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (const Edge &e : graph[u]) {
                if (e.flow < e.cap && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }

        return level[t] != -1;
    }

    int sendFlow(int u, int t, int pushed) {
        if (u == t) return pushed;

        for (int &cid = ptr[u]; cid < (int)graph[u].size(); ++cid) {
            Edge &e = graph[u][cid];

            if (e.flow < e.cap && level[e.to] == level[u] + 1) {
                int tr = sendFlow(e.to, t, min(pushed, e.cap - e.flow));

                if (tr > 0) {
                    e.flow += tr;
                    graph[e.to][e.rev].flow -= tr;
                    return tr;
                }
            }
        }

        return 0;
    }

    long long maxFlow(int s, int t) {
        long long total = 0;

        while (buildLevels(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);

            while (true) {
                int pushed = sendFlow(s, t, INT_MAX);
                if (pushed == 0) break;
                total += pushed;
            }
        }

        return total;
    }
};

int main() {
    int N, T;
    scanf(" %d %d", &N, &T);

    Point bad(0, 0, 0);
    char ch;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);

            int type = cellType(ch);
            int num = cellValue(ch);

            cells[i][j] = type;

            if (type == ROOM && num > 0) {
                survivors.push_back(Point(i, j, num));
            }

            if (type == BAD_REAC) {
                bad = Point(i, j, 0);
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);

            int type = cellType(ch);
            int num = cellValue(ch);

            if (type == CAPS && num > 0) {
                pods.push_back(Point(i, j, num));
                podCount[i][j] = num;
            }
        }
    }

    Dinic dinic(MAXN);
    int source = 0;
    int sink = MAXN - 1;

    for (size_t i = 0; i < survivors.size(); ++i) {
        dinic.addEdge(source, (int)i * 2 + 1, survivors[i].number);
    }

    for (size_t i = 0; i < pods.size(); ++i) {
        dinic.addEdge((int)i * 2 + 2, sink, pods[i].number);
    }

    propagateVenom(bad.x, bad.y, T, N);

    for (size_t i = 0; i < survivors.size(); ++i) {
        for (size_t j = 0; j < pods.size(); ++j) {
            int t = distTo(survivors[i], pods[j], N, T);

            if (t <= T) {
                dinic.addEdge((int)i * 2 + 1, (int)j * 2 + 2, 999);
            }
        }
    }

    printf("%lld\n", dinic.maxFlow(source, sink));
    return 0;
}
